// Compile the actual native shadow passes for the project's Android APIs.
// Public ShaderData API, no player build, package/settings changes or APK.
// Vulkan/GLES3x return all linked stages from ShaderType.Vertex; Fragment is empty.
if(UnityEditor.EditorApplication.isPlaying)throw new System.Exception("Stop Play before shader compiler validation");
var shader=UnityEngine.Resources.Load<UnityEngine.Shader>("EchoSphere/NativeUiAlphaShadow");if(shader==null)throw new System.Exception("Native shadow shader missing");
var data=UnityEditor.ShaderUtil.GetShaderData(shader);var cases=new System.Collections.Generic.List<(int pass,UnityEditor.Rendering.ShaderCompilerPlatform platform,UnityEditor.Rendering.ShaderType stage,string[] keywords)>();
for(int pass=0;pass<3;pass++)foreach(var platform in new[]{UnityEditor.Rendering.ShaderCompilerPlatform.Vulkan,UnityEditor.Rendering.ShaderCompilerPlatform.GLES3x})foreach(var stage in new[]{UnityEditor.Rendering.ShaderType.Vertex})foreach(bool linear in new[]{false,true})cases.Add((pass,platform,stage,linear?new[]{"_UIE_OUTPUT_LINEAR"}:System.Array.Empty<string>()));
int index=0;var rows=new System.Collections.Generic.List<object>();double deadline=UnityEditor.EditorApplication.timeSinceStartup+180;
UnityEditor.EditorApplication.CallbackFunction tick=null;
void Finish(string result){UnityEditor.EditorApplication.update-=tick;System.IO.File.WriteAllText(System.IO.Path.Combine(UnityEngine.Application.dataPath,"../Library/native-ui-shadow-android.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new{result,checks=rows.Count,rows},Newtonsoft.Json.Formatting.Indented));UnityEditor.SessionState.SetString("EchoNativeShadowAndroid",result);}
tick=()=>{try{if(UnityEditor.EditorApplication.timeSinceStartup>deadline)throw new System.Exception("Compiler deadline");var c=cases[index];var compiled=data.GetSubshader(0).GetPass(c.pass).CompileVariant(c.stage,c.keywords,c.platform,UnityEditor.BuildTarget.Android);var messages=compiled.Messages.Select(m=>new{m.message,m.line,severity=m.severity.ToString()}).ToArray();rows.Add(new{index,c.pass,platform=c.platform.ToString(),stage=c.stage.ToString(),c.keywords,compiled.Success,bytes=compiled.ShaderData?.Length??0,messages});if(!compiled.Success||compiled.ShaderData==null||compiled.ShaderData.Length==0||compiled.Messages.Any(m=>m.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error))throw new System.Exception("Compile failed at "+index+" "+c.platform+" pass "+c.pass);if(++index==cases.Count)Finish("PASS 12 Android Vulkan/GLES3 linked vertex/fragment programs");}catch(System.Exception e){Finish("FAIL "+e.GetBaseException().Message);}};
UnityEditor.EditorApplication.update+=tick;UnityEditor.SessionState.SetString("EchoNativeShadowAndroid","RUNNING");return "Compiling 12 Android linked shader programs through public ShaderData API";
